/**
 * The Accuser
 * -----------
 * In the heavenly court the Lord asks Satan about Job; the adversary asks for permission to test him, and the hand of loss begins. Stage: a cosmic court, a throne of light and a figure in shadow, the earth in miniature below; a single day that will undo everything.
 *
 * Palette 0x2d1a0e → 0x060402 · light: dusk · hero: throne
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./job-kit.js.
 */

import { THREE, createScene, column, throne, person } from './job-kit.js';

const BG = 0x2d1a0e;
const GROUND = 0x060402;

export function build(group) {
    const W = createScene(group, { seed: 1695866940, bg: BG, fogNear: 50, fogFar: 200 });

    /* light — dusk */
    W.lights({ sky: 0x7a5a8c, gnd: 0x3a2a1a, hemi: 0.6, sun: 0xff9a50, sunI: 0.85, sunPos: [45, 12, -18] });

    W.disc([55, 22, -140], 12, 0xff9a50);
    W.disc([55, 22, -150], 20, 0xff7a30, 0.18);
    W.stars(30, 150, [0xd8c8e8, 0xc8b8d8], 0.5);
    W.disc([-60, 40, -150], 30, 0x4a3a5c, 0.25);

    /* ground */
    W.ground(260, 260, 0, 0, 0x060402, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* palace: columns, banners and the throne */
    for (let i = -2; i <= 2; i++) column(W, group, i * 8, 0, -30, 11, 1.3, 0x060402, { band: 0x22140b });
    throne(W, group, 0, 0, -24, 1.4, { gold: 0x1d1109 });

    /* hero: the throne */
    throne(W, group, 0, 0, 0, 1.5, { gold: 0x1d1109 });

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0xe8dcc0, head: 'crown', collar: 0xe0b040, ry: -0.49, s: 1.09 });
    person(W, group, [4.5, 0, 6], { robe: 0xe8dcc0, head: 'crown', collar: 0xe0b040, ry: -0.51, s: 1.11 });
    person(W, group, [1, 0, -5], { robe: 0xe8dcc0, head: 'crown', collar: 0xe0b040, ry: 0.52, s: 1.10 });

    return W.finish();
}

export default { build };
